import{_ as t,o as a,c as s,a6 as o}from"./chunks/framework.CswKMrA6.js";const r="/v/2026.11.0/img/strategies/add-dashboard.webp",i="/v/2026.11.0/img/strategies/configure.webp",n="/v/2026.11.0/img/strategies/lcars-shell.webp",m=JSON.parse(`{"title":"Dashboard Strategies","description":"Dashboard strategies: dashboards LCARdS builds for you from a few settings. Create one from Home Assistant's Add dashboard dialog, change its settings, take control to edit it. The LCARS Dashboard (lcars-shell) and its options.","frontmatter":{"description":"Dashboard strategies: dashboards LCARdS builds for you from a few settings. Create one from Home Assistant's Add dashboard dialog, change its settings, take control to edit it. The LCARS Dashboard (lcars-shell) and its options."},"headers":[],"relativePath":"getting-started/dashboard-strategies.md","filePath":"getting-started/dashboard-strategies.md","lastUpdated":1794784043000}`),d={name:"getting-started/dashboard-strategies.md"};function h(l,e,c,g,p,u){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="dashboard-strategies" tabindex="-1">Dashboard Strategies <a class="header-anchor" href="#dashboard-strategies" aria-label="Permalink to &quot;Dashboard Strategies&quot;">​</a></h1><p><strong>A dashboard strategy builds a whole dashboard for you from a few settings.</strong> You pick it in Home Assistant&#39;s Add dashboard dialog, choose a few helpers, and LCARdS draws the screen. The dashboard stores only the settings, so it stays current as your home changes.</p><ul><li>A strategy dashboard rebuilds itself when you add, rename or move areas, devices or entities. While it does, you can change its settings but not its cards.</li><li>To change the cards, <strong>take control</strong>: Home Assistant saves what the strategy made as an ordinary dashboard, and you edit it like any other. The strategy no longer runs after that.</li><li>LCARdS has one dashboard strategy so far, the <a href="#lcars-dashboard">LCARS Dashboard</a>. More are on the way.</li><li>For single sections that fill themselves inside your own sections dashboard, see <a href="./section-strategies.html">Section Strategies</a>.</li></ul><table tabindex="0"><thead><tr><th>Strategy</th><th>In the Add dashboard dialog</th><th>What it builds</th></tr></thead><tbody><tr><td><a href="#lcars-dashboard"><code>custom:lcars-shell</code></a></td><td>LCARS Dashboard</td><td>A full-screen LCARS frame with a page menu and a room light panel</td></tr></tbody></table><h2 id="create-a-strategy-dashboard" tabindex="-1">Create a strategy dashboard <a class="header-anchor" href="#create-a-strategy-dashboard" aria-label="Permalink to &quot;Create a strategy dashboard&quot;">​</a></h2><p><strong>Strategy dashboards are created from Settings → Dashboards, like any other dashboard.</strong> LCARdS must be installed and Home Assistant reloaded once, so the browser has loaded LCARdS.</p><ol><li>Open <strong>Settings → Dashboards</strong> and select <strong>Add dashboard</strong>.</li><li>Under <strong>Community dashboards</strong>, pick <strong>LCARS Dashboard</strong>.</li><li>Pick the helpers for each setting (see <a href="#helpers-to-create">Helpers to create</a>) and select <strong>Next</strong>. Every setting can stay empty: the room panel and the page menu then show a hint, and you can pick helpers later.</li><li>Give the dashboard a title and an icon, and select <strong>Create</strong>.</li></ol><p><img src="'+r+'" alt="The Add dashboard dialog: LCARS Dashboard under Community dashboards"></p><details class="details custom-block"><summary>More about creating one</summary><ul><li><strong>Not in the list:</strong> the Community dashboards heading appears only when the browser has loaded LCARdS. Reload the page (Ctrl+Shift+R) after installing or updating, and check that the LCARdS integration is set up under <strong>Settings → Devices &amp; services</strong>.</li><li><strong>YAML dashboards:</strong> a dashboard kept in a YAML file can use a strategy too: put the settings under <code>strategy:</code> at the top of the file, as in the <a href="#settings">example below</a>.</li></ul></details><h2 id="change-the-settings" tabindex="-1">Change the settings <a class="header-anchor" href="#change-the-settings" aria-label="Permalink to &quot;Change the settings&quot;">​</a></h2><p><strong>Open the dashboard, select the pencil, and the Edit dashboard dialog shows the strategy&#39;s settings.</strong> Change a helper and the screen rebuilds when you save.</p><p><img src="'+i+'" alt="The strategy&#39;s settings: room selector, page selector, top bar toggle and right sidebar toggle"></p><ul><li>The dialog&#39;s three-dot menu has <strong>Edit in YAML</strong>, which shows the settings as YAML, and <strong>Take control</strong> (see <a href="#take-control">Take control</a>).</li><li>Only administrators see the pencil.</li></ul><h2 id="when-it-rebuilds" tabindex="-1">When it rebuilds <a class="header-anchor" href="#when-it-rebuilds" aria-label="Permalink to &quot;When it rebuilds&quot;">​</a></h2><p><strong>Home Assistant rebuilds a strategy dashboard when your areas, devices, entities or floors change, and when you change its settings.</strong> You don&#39;t need to reload the page.</p><ul><li>Adding a light to an area, renaming an area or creating a new one shows up on the screen within a moment.</li><li>Changing a state (turning a light on, picking a room) doesn&#39;t rebuild anything. The cards follow states themselves, so the screen stays fast.</li><li>A helper you rename or delete has to be picked again in the settings.</li></ul><h2 id="take-control" tabindex="-1">Take control <a class="header-anchor" href="#take-control" aria-label="Permalink to &quot;Take control&quot;">​</a></h2><p><strong>Take control turns the strategy&#39;s output into an ordinary dashboard you can edit.</strong> Use it when you want to fill the frame with your own cards, move parts or change colours.</p><ul><li>Select the pencil, then <strong>Take control</strong> in the Edit dashboard dialog&#39;s three-dot menu. Home Assistant asks you to confirm, then saves every card the strategy made.</li><li>After that the dashboard no longer rebuilds: new areas and lights don&#39;t appear by themselves. Create a new strategy dashboard if you want both.</li><li>The LCARS Dashboard is one <a href="./../cards/layout-view/">layout view</a>, so after taking control you edit it with the layout view&#39;s own editor.</li></ul><h2 id="lcars-dashboard" tabindex="-1">LCARS Dashboard <a class="header-anchor" href="#lcars-dashboard" aria-label="Permalink to &quot;LCARS Dashboard&quot;">​</a></h2><p><strong><code>custom:lcars-shell</code> draws a full-screen LCARS frame: corner sweeps, header and footer bars, a page menu on the left and a room light panel in the middle.</strong> It is a starting point: the header, the top bar and the right sidebar hold placeholder labels for you to replace after you <a href="#take-control">take control</a>.</p><p><img src="'+n+`" alt="The LCARS Dashboard: corner sweeps, a page menu of Alpha, Beta and Gamma on the left, a room panel listing two rooms with an orange and a blue lamp slider at their brightness, a header bar and a right sidebar"></p><ul><li><strong>Room light panel:</strong> a list of rooms and, next to it, a slider for each light in the picked room. Tap a slider to toggle the light, hold it for its more-info dialog. A room without lights says so.</li><li><strong>Page menu:</strong> the options of your page selector as buttons in the left sidebar. Picking one only sets the helper; nothing on the screen changes. After you take control, give your cards a Visibility condition on that helper to show them on one page.</li><li><strong>Top bar and right sidebar:</strong> the two buttons under the top left corner toggle them, through two <code>input_boolean</code> helpers. Without the helpers the buttons are still drawn but do nothing; the top bar is left out and the right sidebar always shows.</li><li>An <a href="./../cards/alert-overlay/">alert overlay</a> sits over the top left corner and shows during an alert.</li></ul><h3 id="helpers-to-create" tabindex="-1">Helpers to create <a class="header-anchor" href="#helpers-to-create" aria-label="Permalink to &quot;Helpers to create&quot;">​</a></h3><p><strong>The shell reads up to four helpers; create them in Settings → Devices &amp; services → Helpers → Create helper.</strong> Each one is optional.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Helper</th><th>What to put in it</th></tr></thead><tbody><tr><td>Room selector</td><td>Dropdown (<code>input_select</code>) or Text (<code>input_text</code>)</td><td>A Dropdown: one option per room, spelled exactly like the area&#39;s name (or its area id). A Text: nothing, the shell lists your areas and stores the one picked</td></tr><tr><td>Page selector</td><td>Dropdown (<code>input_select</code>)</td><td>One option per page, for example <code>Main</code>, <code>Engineering</code>, <code>Sensors</code></td></tr><tr><td>Top bar toggle</td><td>Toggle (<code>input_boolean</code>)</td><td>Nothing; on shows the top bar</td></tr><tr><td>Right sidebar toggle</td><td>Toggle (<code>input_boolean</code>)</td><td>Nothing; on shows the right sidebar</td></tr></tbody></table><h3 id="room-selector-modes" tabindex="-1">Room selector modes <a class="header-anchor" href="#room-selector-modes" aria-label="Permalink to &quot;Room selector modes&quot;">​</a></h3><p><strong>The room selector decides where the room list comes from.</strong> Pick a Text helper to list every area with no upkeep; pick a Dropdown to show only some rooms, in your own order. Both show the same light lists.</p><ul><li><strong>A Dropdown (<code>input_select</code> or <code>select</code>):</strong> its options are the rooms, in your order. Spell each option exactly like an area&#39;s name in Settings → Areas, labels &amp; zones, capitals included (or use the area id). An option that matches no area shows &quot;No lights in this room&quot;. New areas need a new option.</li><li><strong>A Text helper (<code>input_text</code>):</strong> the room list is every area in Home Assistant, sorted by name, with its icon. Picking a room stores its area id in the helper. New areas appear on their own.</li><li>A light belongs to a room through its own area, or else its device&#39;s area. Hidden lights and lights with an entity category (configuration lights such as status LEDs) are left out.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p><strong>These are the keys of the dashboard&#39;s <code>strategy:</code> block; the settings dialog writes them for you.</strong> The example is the whole dashboard config; <strong>Edit in YAML</strong> shows the lines under <code>strategy:</code>. It is a whole dashboard, so it can&#39;t render inside this page.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">strategy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcars-shell</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  room_selector_entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_select.lcars_room</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  page_selector_entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_select.lcars_page</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  top_bar_entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.lcars_top_bar</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  right_sidebar_entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.lcars_right_sidebar</span></span></code></pre></div><details class="details custom-block"><summary>More about the LCARS Dashboard</summary><ul><li><strong>One view:</strong> the dashboard has a single view at <code>/&lt;dashboard&gt;/lcars</code>, a <a href="./../cards/layout-view/">layout view</a> sized to the screen. It is built from LCARdS cards only, so it needs no other custom cards.</li><li><strong>Narrow screens:</strong> below 1010 px wide the gap before the right sidebar narrows to 1 px.</li><li><strong>Colours:</strong> every colour comes from your theme&#39;s LCARS variables, so <a href="./../core/themes/">alert modes</a> recolour the frame.</li><li><strong>&quot;Configuration error&quot; in the room panel:</strong> before 2026.11 the room lists used the auto-entities card from HACS, and without it each room showed this error. Since 2026.11 LCARdS reads the lights from your areas itself: update LCARdS and hard refresh the page (Ctrl+Shift+R).</li></ul></details><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>required</td><td><code>custom:lcars-shell</code></td></tr><tr><td><code>room_selector_entity</code></td><td>string</td><td>-</td><td>An <code>input_select</code>, <code>select</code> or <code>input_text</code> that picks the room. Empty shows a hint in the room panel</td></tr><tr><td><code>page_selector_entity</code></td><td>string</td><td>-</td><td>An <code>input_select</code> or <code>select</code> whose options become the page menu. Empty shows a hint in the sidebar</td></tr><tr><td><code>top_bar_entity</code></td><td>string</td><td>-</td><td>An <code>input_boolean</code> that shows or hides the top bar. Empty leaves the top bar out</td></tr><tr><td><code>right_sidebar_entity</code></td><td>string</td><td>-</td><td>An <code>input_boolean</code> that shows or hides the right sidebar. Empty keeps the sidebar shown</td></tr></tbody></table>`,34)])])}const y=t(d,[["render",h]]);export{m as __pageData,y as default};
